layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); border-left: 9px solid rgb(176, 37, 24); border-radius: 0px; font-family: var(--ryt-font-body); font-size: 20px; font-weight: 800; font-style: normal; line-height: 1.62; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 24px; transition: all; border-top: none; border-right: none; border-bottom: none }
article[data-ryt="rec-card"] { border-bottom: 1px solid var(--ryt-text); border-radius: 0px; transition: transform 0.25s; border-top: none; border-right: none; border-left: none }
[data-ryt="footer"] { color: var(--ryt-muted); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-text); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 4.8px; transition: all }
[data-ryt="section"] > h2 { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 850; font-style: normal; line-height: 0.8; letter-spacing: -5.76px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="review"] { color: var(--ryt-muted); font-family: var(--ryt-font-body); font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: 12.48px; font-weight: 400; font-style: normal; line-height: 1.62; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 850; font-style: normal; letter-spacing: -1.584px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(176, 37, 24); text-decoration-thickness: 2.304px; text-underline-offset: 5.184px; transition: all }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 40px; font-weight: 850; font-style: normal; line-height: 0.96; letter-spacing: -2.688px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="header"] { border-top: 2px solid var(--ryt-text); border-bottom: 2px solid var(--ryt-text) }
[data-ryt="nav"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 14.08px; font-weight: 900; font-style: normal; line-height: 1; letter-spacing: 0.2816px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 2.5344px; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="button"] { color: var(--ryt-bg); background-color: var(--ryt-text); border-radius: 0px; font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-weight: 800; font-style: normal; line-height: 1.2; letter-spacing: 0.624px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 7.2px; padding-right: 9.6px; padding-bottom: 7.2px; padding-left: 9.6px; transition: all }
body { background-image: url("{{assets}}/no-fate_15da70308e01/wild-paper-grain.0ae906a7b4e660100385ef72da3f61c5183cdae6260ac7a734158f198474e578.webp"); background-size: 768px 768px; background-position: 0% 0%; background-repeat: repeat }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 28.8px; font-weight: 850; font-style: normal; line-height: 0.95; letter-spacing: -1.584px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { text-decoration-line: underline }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { text-decoration-line: underline }
article[data-ryt="rec-card"]:hover { transform: translateY(-2px); transform: none; color: #f3efe4 }
